package rpc

import (
	"context"
	"errors"
	"github.com/nezhahq/nezha/model"
	"time"
)

// Callers authorize execution; commands are generated by the tmux adapter.
func RunTerminalManagementCommand(ctx context.Context, server *model.Server, command string) (string, error) {
	return runTerminalCommand(ctx, server, command, 12*time.Second)
}
func RunTerminalInstallCommand(ctx context.Context, server *model.Server, command string) (string, error) {
	return runTerminalCommand(ctx, server, command, 330*time.Second)
}
func runTerminalCommand(ctx context.Context, server *model.Server, command string, limit time.Duration) (string, error) {
	r, status := insightCommandRunner(server, "terminal-session")(ctx, command, limit)
	if status != "" {
		return "", errors.New("服务器暂时不可用或响应超时，请稍后刷新")
	}
	if r == nil || !r.Successful {
		return "", errors.New("tmux 操作失败，请检查权限、会话名称及 Agent 是否允许执行命令")
	}
	return r.Data, nil
}
